  describe('with asChild', () => {
    it('should only call function refs once', async () => {
      render(
        <Input asChild ref={handleRef}>
          <input />
        </Input>,
      );
      await userEvent.type(screen.getByRole('textbox'), 'foo');
      expect(handleRef).toHaveBeenCalledTimes(1);
    });
  });

  describe('with a ref callback that schedules an update', () => {
    it('should not exceed the maximum update depth', async () => {
      const App = () => {
        const [, setTick] = React.useState(0);
        const handleRef = React.useCallback((node: HTMLInputElement | null) => {
          // mimic editor frameworks (eg. Slate/Plate) that schedule an update
          // (eg. `editor.onChange`) when a ref changes
          void node;
          setTick((t) => t + 1);
        }, []);
        return (
          <Input asChild ref={handleRef}>
            <input />
          </Input>
        );
      };
      expect(() => render(<App />)).not.toThrow();
      expect(screen.getByRole('textbox')).toBeTruthy();
    });
  });
});

